508:       }
509: 
510:       let accepted = false;
511:       try {
512:         const response = await apiService.post(`/api/canvas/${submission.canvasId}/submit`, {
513:           form_data: submission.formData,
514:           submitted_at: submission.submittedAt,
515:         });
516:         accepted = response.success;
